    (38, 'Establishment of justice', 'عدل کا قیام', 'د عدل ټینګول'),
    (39, 'Warning for the hypocrites', 'منافقین کے لیے وعید', 'منافقانو ته ګواښ'),
    (40, 'Deception of the hypocrites and its punishment', 'منافقین کی دھوکہ دہی اور سزا', 'د منافقانو دوکه او سزا'),
    (41, 'Crimes of the People of the Book and their punishment', 'اہلِ کتاب کے جرائم اور سزا', 'د اهل کتابو جرمونه او سزا'),
